/bin/zsh -lc "python3 review/global-independent-review/seventh-2026-10-14-e646432-7a91/audit_tool.py command --directory tasks/R7-D01/logs --id 002-prior-ledger-shapes -- python3 - <<'PY'
from pathlib import Path
import json
p=Path('review/global-independent-review/seventh-2026-10-14-e646432-7a91')
for mod,names in [('R7-M16',['report.md','task.json','attestations.json','reading-ledger.json','consumer-discovery.json']),('R7-M01',['task.json','report.md','forward-map.json','reverse-map.json','reading-ledger.json'])]:
 for name in names:
  q=p/'tasks'/mod/name
  if name.endswith('.md'): print(q, q.read_text())
  else:
   j=json.loads(q.read_text());print(q,'bytes',q.stat().st_size,'type',type(j).__name__,'shape',[(k, len(v) if isinstance(v,(list,dict)) else v) for k,v in j.items()] if isinstance(j,dict) else len(j))
print('inventory files')
for name in ['source','formal','supplements']:
 j=json.loads((p/'inventory'/f'{name}.json').read_text());print(name,len(j),j[:1])
PY"

